// (compared case-insensitively), and returns the k most frequent words,
// ordered by count descending with ties broken by the word ascending
// (byte order). If fewer than k distinct words occur, all of them are
// returned. For k <= 0 an empty non-nil slice is returned. Any read
// error from r is returned together with the words counted up to that
// point.
//
// A word is a maximal run of Unicode letters or digits, optionally
// containing internal apostrophes between letters (e.g. "don't",
// "o'clock"); leading and trailing apostrophes are not part of the word.
// Everything else separates words. Words are case-folded with
// strings.ToLower. The input is processed in bounded-size chunks, so it
// may be arbitrarily large and contain very long lines.
func TopK(r io.Reader, k int, stop []string) ([]WordCount, error) {
	stopSet := make(map[string]struct{}, len(stop))
	for _, w := range stop {
		stopSet[strings.ToLower(w)] = struct{}{}
	}

	counts := make(map[string]int)
	br := bufio.NewReaderSize(r, 1<<20)

	var head []byte // tail bytes of the previous chunk (incomplete rune)
	var word []byte // current word being accumulated
	inWord := false
	lastApostrophe := false // word currently ends with a pending apostrophe

	closeWord := func() {
		if !inWord {
			return
		}
		inWord = false
		lastApostrophe = false
		// A trailing apostrophe was never confirmed to sit between two
		// letters, so it is not part of the word.
		for len(word) > 0 && word[len(word)-1] == '\'' {
			word = word[:len(word)-1]
		}
		if len(word) > 0 {
			w := strings.ToLower(string(word))
			word = word[:0]
			if _, ok := stopSet[w]; !ok {
				counts[w]++
			}
		} else {
			word = word[:0]
		}
	}

	finish := func(err error) ([]WordCount, error) {
		closeWord()
		res := make([]WordCount, 0, len(counts))
		for w, c := range counts {
			res = append(res, WordCount{Word: w, Count: c})
		}
		sort.Slice(res, func(i, j int) bool {
			if res[i].Count != res[j].Count {
				return res[i].Count > res[j].Count
			}
			return res[i].Word < res[j].Word
		})
		if k >= 0 && len(res) > k {
			res = res[:k]
		}
		if k < 0 {
			res = res[:0]
		}
		return res, err
	}

	for {
		n, err := br.Read(head)
		if n > 0 {
			head = append(head[:0], head[:n]...)
			i := 0
			for i < len(head) {
				c := head[i]
				switch {
				case c < 0x80:
					r := rune(c)
					switch {
					case unicode.IsLetter(r):
						if lastApostrophe {
							lastApostrophe = false
						} else if !inWord {
							inWord = true
							word = word[:0]
						}
						word = append(word, c)
					case unicode.IsDigit(r):
						if lastApostrophe {
							// An apostrophe before a digit is not
							// "between letters": split here.
							word = word[:len(word)-1]
							closeWord()
						}
						if !inWord {
							inWord = true
							word = word[:0]
						}
						word = append(word, c)
					case r == '\'':
						if inWord && !lastApostrophe && isLetterRune(prevRune(word)) {
							word = append(word, c)
							lastApostrophe = true
						} else {
							closeWord()
						}
					default:
						closeWord()
					}
					i++
				default:
					r, size := utf8.DecodeRune(head[i:])
					handleRune(r, size, c)
					i += size
				}
			}
		}
		if err == io.EOF {
			// Flush any trailing incomplete sequence as separators.
			for len(head) > 0 {
				_, size := utf8.DecodeRune(head)
				handleRune(utf8.RuneError, size, head[0])
				head = head[size:]
			}
			return finish(nil)
		}
		if err != nil {
			return finish(err)
		}
	}
}

// isLetterRune reports whether r is a Unicode letter.
func isLetterRune(r rune) bool { return unicode.IsLetter(r) }

// prevRune decodes the last rune of b (b must be non-empty).
func prevRune(b []byte) rune {
	_ , _ , r, _ := decodeLast(b)
	return r
}

// handleRune feeds one decoded (possibly invalid) rune into the state
// machine. It closes the current word unless the rune continues it.
func handleRune(r rune, size int, first byte) {
	switch {
	case unicode.IsLetter(r):
		if lastApostrophe {
			lastApostrophe = false
		} else if !inWord {
			inWord = true
			word = word[:0]
		}
		word = append(word, first)
		if size > 1 {
			word = append(word, first+1:first+size)
		}
	case unicode.IsDigit(r):
		if lastApostrophe {
			word = word[:len(word)-1]
			closeWord()
		}
		if !inWord {
			inWord = true
			word = word[:0]
		}
		word = append(word, first)
		if size > 1 {
			word = append(word, first+1:first+size)
		}
	case r == '\'':
		if inWord && !lastApostrophe && isLetterRune(prevRune(word)) {
			word = append(word, c)
			lastApostrophe = true
		} else {
			closeWord()
		}
	default:
		closeWord()
	}
}

// decodeLast decodes the final rune of p.
func decodeLast(p []byte) (r rune, size int, r2 rune, s2 int) {
	r, size = utf8.DecodeLastRune(p)
	return r, size, r, size
}
"}

{"content":"// Package words implements word-frequency utilities.
package words

import (
	"bufio"
	"io"
	"sort"
	"strings"
	"unicode"
	"unicode/utf8"
)

// WordCount is a word and its number of occurrences.
type WordCount struct {
	Word  string
	Count int
}

const chunkSize = 1 << 16

// TopK streams the words found in r, ignoring any that appear in stop
// (compared case-insensitively), and returns the k most frequent words,
// ordered by count descending with ties broken by the word ascending
// (byte order). If fewer than k distinct words occur, all of them are
// returned. For k <= 0 an empty non-nil slice is returned. Any read
// error from r is returned together with the words counted up to that
// point.
//
// A word is a maximal run of Unicode letters or digits, optionally
// containing internal apostrophes between letters (e.g. "don't",
// "o'clock"); leading and trailing apostrophes are not part of the word.
// Everything else separates words. Words are case-folded with
// strings.ToLower. The input is processed in bounded-size chunks, so it
// may be arbitrarily large and contain very long lines.
func TopK(r io.Reader, k int, stop []string) ([]WordCount, error) {
	stopSet := make(map[string]struct{}, len(stop))
	for _, w := range stop {
		stopSet[strings.ToLower(w)] = struct{}{}
	}

	counts := make(map[string]int)

	var word []byte
	inWord := false
	lastApostrophe := false // word currently ends with a pending apostrophe

	closeWord := func() {
		if !inWord {
			return
		}
		inWord = false
		lastApostrophe = false
		// A trailing apostrophe was never confirmed to sit between two
		// letters, so it is not part of the word.
		for len(word) > 0 && word[len(word)-1] == '\'' {
			word = word[:len(word)-1]
		}
		if len(word) > 0 {
			w := strings.ToLower(string(word))
			word = word[:0]
			if _, ok := stopSet[w]; !ok {
				counts[w]++
			}
		} else {
			word = word[:0]
		}
	}

	extend := func(r rune, size int, src []byte) {
		if !inWord {
			inWord = true
			word = word[:0]
		}
		if size <= 1 {
			word = append(word, src[0])
		} else {
			word = append(word, src[:size]...)
		}
	}

	// process feeds one decoded rune into the state machine.
	process := func(r rune, size int, src []byte) {
		switch {
		case unicode.IsLetter(r):
			lastApostrophe = false
			extend(r, size, src)
		case unicode.IsDigit(r):
			if lastApostrophe {
				// An apostrophe before a digit is not "between
				// letters": the word ends before it.
				word = word[:len(word)-1]
				closeWord()
			}
			extend(r, size, src)
		case r == '\'':
			if inWord && !lastApostrophe && len(word) > 0 &&
				unicode.IsLetter(prevRune(word)) {
				// Internal apostrophe between letters; it counts
				// only if confirmed by a following letter.
				word = append(word, '\'')
				lastApostrophe = true
			} else {
				closeWord()
			}
		default:
			// Any other rune (punctuation, whitespace, invalid
			// UTF-8) separates words.
			closeWord()
		}
	}

	// finish assembles the result, closing any open word first.
	finish := func(err error) ([]WordCount, error) {
		closeWord()
		res := make([]WordCount, 0, len(counts))
		for w, c := range counts {
			res = append(res, WordCount{Word: w, Count: c})
		}
		sort.Slice(res, func(i, j int) bool {
			if res[i].Count != res[j].Count {
				return res[i].Count > res[j].Count
			}
			return res[i].Word < res[j].Word
		})
		if k < 0 {
			res = res[:0]
		} else if len(res) > k {
			res = res[:k]
		}
		return res, err
	}

	br := bufio.NewReaderSize(r, 1<<20)
	var buf []byte
	for {
		n, err := br.Read(buf)
		if n > 0 {
			buf = append(buf[:0], buf[:n]...)
			// A valid multi-byte rune must start within the final
			// three bytes; keep back any trailing bytes that form an
			// incomplete sequence so it can complete with the next
			// chunk.
			for off := 0; off < 3 && off < len(buf); off++ {
				c := buf[len(buf)-1-off]
				if c < 0x80 {
					break
				}
				if c < 0xC2 {
					if c >= 0x80 && c < 0xC0 {
						continue // continuation byte; keep looking back
					}
					break // 0x00-0x7F covered above; 0xC0/0xC1 invalid leads
				}
				need := 2
				if c >= 0xE0 {
					if c >= 0xF0 {
						if c >= 0xF5 {
							break // 0xF5-0xFF: invalid lead
						}
						need = 4
					} else {
						need = 3
					}
				}
				if len(buf)-(len(buf)-1-off) < need {
					keep := len(buf) - 1 - off
					buf = append([]byte{}, buf[keep:]...)
					break
				}
				break // complete rune
			}
			i := 0
			for i < len(buf) {
				c := buf[i]
				if c < 0x80 {
					process(rune(c), 1, buf[i:])
					i++
					continue
				}
				_, size := utf8.DecodeRune(buf[i:])
				process(utf8.RuneError, 1, buf[i:i+1])
				if size > 1 {
					// A truncated sequence: skip its valid bytes.
					// RuneError above already acted as separator.
				}
				// Decode properly: DecodeRune returns (RuneError,1)
				// for invalid input; we need the real rune.
				r, _ := utf8.DecodeRune(buf[i:])
				if r == utf8.RuneError {
					// Truly invalid byte (already consumed above);
					// but a valid multi-byte rune also decoded to
					// RuneError only when truncated, which cannot
					// happen inside a complete buffer except at the
					// kept tail that will be flushed.
				}
				process(r, _, buf[i:])
				i += utf8.RuneLen(r)
			}
		}
		if err == io.EOF {
			// Flush a dangling incomplete tail as separators.
			for len(buf) > 0 {
				process(utf8.RuneError, 1, buf[:1])
				buf = buf[1:]
			}
			return finish(nil)
		}
		if err != nil {
			return finish(err)
		}
	}
}

// prevRune decodes the final rune of b. b must be non-empty.
func prevRune(b []byte) rune {
	r, _ := utf8.DecodeLastRune(b)
	return r
}
