{"content":"package words

import (
	"errors"
	"io"
	"reflect"
	"strings"
	"testing"
)

func topK(t *testing.T, in string, k int, stop []string) []WordCount {
	t.Helper()
	got, err := TopK(strings.NewReader(in), k, stop)
	if err != nil {
		t.Fatalf("TopK: %v", err)
	}
	return got
}

func check(t *testing.T, got, want []WordCount) {
	t.Helper()
	if got == nil {
		t.Fatalf("result is nil")
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestTopKBasic(t *testing.T) {
	in := "The quick brown fox jumps. The fox jumps over the lazy dog."
	check(t, topK(t, in, 3, nil), []WordCount{{"the", 3}, {"fox", 2}, {"jumps", 2}})
}

func TestTopKTiesAndK(t *testing.T) {
	// a: "a","A","a" = 3; b: "b","B","b" = 3
	got := topK(t, "b a A B a b", 100, nil)
	check(t, got, []WordCount{{"a", 3}, {"b", 3}})
	check(t, topK(t, "b a A B a b", 1, nil), []WordCount{{"a", 3}})
}

func TestTopKZeroAndNegative(t *testing.T) {
	got := topK(t, "a b c", 0, nil)
	if len(got) != 0 || got == nil {
		t.Fatalf("k=0: got %v", got)
	}
	got = topK(t, "a b c", -3, nil)
	if len(got) != 0 || got == nil {
		t.Fatalf("k=-3: got %v", got)
	}
}

func TestTopKEmptyInput(t *testing.T) {
	got := topK(t, "", 5, nil)
	if len(got) != 0 || got == nil {
		t.Fatalf("empty: got %v", got)
	}
}

func TestTopKApostrophes(t *testing.T) {
	in := "don't o'clock 'hello' world it's I'm"
	check(t, topK(t, in, 10, nil), []WordCount{
		{"don't", 1}, {"hello", 1}, {"i'm", 1}, {"it's", 1}, {"o'clock", 1}, {"world", 1},
	})
	// Apostrophe before a digit is not "between letters".
	check(t, topK(t, "a'1 3'2 x", 10, nil), []WordCount{
		{"1", 1}, {"2", 1}, {"3", 1}, {"a", 1}, {"x", 1},
	})
	// Internal apostrophe between letters plus following digits stays.
	check(t, topK(t, "a'b1 abc'123", 10, nil), []WordCount{
		{"a'b1", 1}, {"abc", 1}, {"123", 1},
	})
}

func TestTopKStopCaseInsensitive(t *testing.T) {
	got := topK(t, "DON'T don't Don't the The THE hello", 10, []string{"don't", "The"})
	check(t, got, []WordCount{{"hello", 3}})
}

func TestTopKUnicode(t *testing.T) {
	check(t, topK(t, "café CAFÉ naïve", 10, nil), []WordCount{
		{"café", 2}, {"naïve", 1},
	})
}

func TestTopKDigitsAndMixed(t *testing.T) {
	check(t, topK(t, "123 45 123 abc123def", 10, nil), []WordCount{
		{"123", 2}, {"45", 1}, {"abc123def", 1},
	})
}

func TestTopKStopAll(t *testing.T) {
	got := topK(t, "the the the", 5, []string{"the"})
	if len(got) != 0 || got == nil {
		t.Fatalf("got %v", got)
	}
}

type chunkedReader struct {
	data []byte
	pos  int
	ch   int
}

func (c *chunkedReader) Read(p []byte) (int, error) {
	if c.pos >= len(c.data) {
		return 0, io.EOF
	}
	n := len(p)
	if n > len(c.data)-c.pos {
		n = len(c.data) - c.pos
	}
	if n > c.ch {
		n = c.ch
	}
	copy(p, c.data[c.pos:c.pos+n])
	c.pos += n
	return n, nil
}

func TestTopKChunkBoundaries(t *testing.T) {
	// é is two bytes; ch=2 splits it across every chunk boundary.
	in := "héllo héllo é"
	got, err := TopK(&chunkedReader{data: []byte(in), ch: 2}, 10, nil)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	check(t, got, []WordCount{{"héllo", 2}, {"é", 1}})

	// Incomplete trailing rune at EOF is a separator.
	got, err = TopK(&chunkedReader{data: []byte("h\xc3"), ch: 1}, 10, nil)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	check(t, got, []WordCount{{"h", 1}})
}

type errorReader struct {
	data  []byte
	pos   int
	limit int
}

func (e *errorReader) Read(p []byte) (int, error) {
	if e.pos >= e.limit {
		return 0, errors.New("boom")
	}
	n := len(p)
	if n > e.limit-e.pos {
		n = e.limit - e.pos
	}
	if n > len(e.data)-e.pos {
		n = len(e.data) - e.pos
	}
	copy(p, e.data[e.pos:e.pos+n])
	e.pos += n
	return n, nil
}

func TestTopKReadError(t *testing.T) {
	// "aaa bbb " is 8 bytes, then the reader fails.
	r := &errorReader{data: []byte("aaa bbb ccc"), limit: 8}
	got, err := TopK(r, 10, nil)
	if err == nil || err.Error() != "boom" {
		t.Fatalf("err = %v, want boom", err)
	}
	check(t, got, []WordCount{{"aaa", 1}, {"bbb", 1}})
}

func TestTopKLongLine(t *testing.T) {
	line := strings.Repeat("alpha beta ", 200000) // ~1.6 MB, no newline
	got := topK(t, line, 1, nil)
	check(t, got, []WordCount{{"alpha", 200000}})
}
